// Shared markup for the experimental-feature marker. Exp.astro uses it for
// JSX call sites; frontmatter strings rendered with set:html (FAQ answers)
// call expHtml() directly so the marker stays one implementation.
// `name` must be registered in web/src/data/experimental.json (generated by
// `task docs:experimental` from internal/experiments); an unknown name
// throws and fails the build.
import features from '../data/experimental.json';

export interface ExpFeature {
  name: string;
  group: string;
  summary: string;
  doc: string;
  ticket: string;
  state: string;
}

export function expFeature(name: string): ExpFeature {
  const feature = (features as ExpFeature[]).find((f) => f.name === name);
  if (!feature) {
    throw new Error(`Exp: "${name}" is not a registered experimental feature; see web/src/data/experimental.json`);
  }
  return feature;
}

function escapeAttr(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

export function expHtml(name: string): string {
  const f = expFeature(name);
  const title = escapeAttr(`Experimental (${f.name}): ${f.summary}`);
  return `<sup class="exp"><a href="/docs/experimental" title="${title}">e</a></sup>`;
}
